import{_ as a,o,c as s,a3 as e}from"./chunks/framework.qCVWde4n.js";const u=JSON.parse('{"title":"状态页：看现场","description":"","frontmatter":{},"headers":[],"relativePath":"use/status-page.md","filePath":"use/status-page.md","lastUpdated":null}'),r={name:"use/status-page.md"};function l(n,t,i,d,p,c){return o(),s("div",null,[...t[0]||(t[0]=[e(`<h1 id="状态页-看现场" tabindex="-1">状态页：看现场 <a class="header-anchor" href="#状态页-看现场" aria-label="Permalink to &quot;状态页：看现场&quot;">​</a></h1><p><strong>框架最有诊断价值的一页。</strong> 它告诉你「现在游戏内到底是什么状况」。</p><h2 id="页面上有什么" tabindex="-1">页面上有什么 <a class="header-anchor" href="#页面上有什么" aria-label="Permalink to &quot;页面上有什么&quot;">​</a></h2><ol><li><strong>偏离原版的参数清单</strong> —— 最重要的部分</li><li><strong>战役信息</strong> —— 回合、威望</li><li><strong>战斗现场</strong> —— 是否玩家回合、装填状态等</li><li><strong>运行状态</strong> —— 各项是否正常</li></ol><h2 id="偏离清单-这一页的核心" tabindex="-1">偏离清单：这一页的核心 <a class="header-anchor" href="#偏离清单-这一页的核心" aria-label="Permalink to &quot;偏离清单：这一页的核心&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">这是什么</p><p>它遍历<strong>所有参数</strong>，把<strong>当前值不等于默认值</strong>的那些列出来。</p><p>比如你改了主炮伤害和威望倍率，这里就会显示：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>偏离原版的参数：</span></span>
<span class="line"><span>  combat.gun.damageMul    1.5   (原版 1.0)</span></span>
<span class="line"><span>  economy.renownGainMul   2.0   (原版 1.0)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><strong>刚装好框架时，这里应该是空的。</strong></p></div><h3 id="为什么这一页这么重要" tabindex="-1">为什么这一页这么重要 <a class="header-anchor" href="#为什么这一页这么重要" aria-label="Permalink to &quot;为什么这一页这么重要&quot;">​</a></h3><p>它解决了一个很常见的困惑：</p><blockquote><p>「我怎么感觉数值不对劲？是不是有什么被改过了？」</p></blockquote><p>不用猜、不用一个一个翻参数页 —— <strong>直接看这个清单</strong>。</p><h3 id="什么时候会用到" tabindex="-1">什么时候会用到 <a class="header-anchor" href="#什么时候会用到" aria-label="Permalink to &quot;什么时候会用到&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>用法</th></tr></thead><tbody><tr><td>刚装好，验证干净</td><td>清单应该是<strong>空的</strong></td></tr><tr><td>怀疑数值被动过</td><td>清单列出所有偏离</td></tr><tr><td>想知道自己改了啥</td><td>一眼看全</td></tr><tr><td>排查奇怪现象</td><td>确认是不是参数导致的</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">如果清单里有你没印象改过的项</p><p>可能是：</p><ol><li><strong>某个 Mod 改的</strong> —— 去 <a href="/AtlanticFleetSite/docs/use/mods-page">Mod 页</a> 看装了哪些</li><li><strong>上次改的忘了</strong> —— 这是最常见的，清单帮你回忆</li></ol><p>两种情况都可以用参数页「恢复默认」清空。</p></div><h2 id="战役信息" tabindex="-1">战役信息 <a class="header-anchor" href="#战役信息" aria-label="Permalink to &quot;战役信息&quot;">​</a></h2><p>显示当前战役的：</p><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td><strong>回合数</strong></td><td>当前进行到第几回合</td></tr><tr><td><strong>威望</strong></td><td>当前有多少威望</td></tr></tbody></table><p>和 <a href="/AtlanticFleetSite/docs/use/save-page">存档页</a> 显示的是同一份数据，但这里是<strong>只读查看</strong>。</p><h2 id="战斗现场" tabindex="-1">战斗现场 <a class="header-anchor" href="#战斗现场" aria-label="Permalink to &quot;战斗现场&quot;">​</a></h2><p>如果在战斗中，这里会显示实时状态：</p><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td><strong>是否玩家回合</strong></td><td>现在轮到谁行动</td></tr><tr><td><strong>主炮装填</strong></td><td>可以射击的炮数</td></tr><tr><td><strong>鱼雷装填</strong></td><td>已装填的鱼雷管数</td></tr><tr><td><strong>当前倍速</strong></td><td>时间缩放值</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">这个探针是为什么加的</p><p>早期排查「为什么点了发射没反应」时，靠猜很难定位。</p><p>有了这个实时探针，就能<strong>直接看到</strong>：</p><ul><li>现在是不是你的回合</li><li>主炮到底能不能打</li><li>倍速是不是被调过了</li></ul><p><strong>把「猜」变成「看」。</strong></p></div><h3 id="关于战斗规则的一个说明" tabindex="-1">关于战斗规则的一个说明 <a class="header-anchor" href="#关于战斗规则的一个说明" aria-label="Permalink to &quot;关于战斗规则的一个说明&quot;">​</a></h3><p>如果你看到「主炮已装填但点发射没反应」，请注意游戏的实际规则：</p><div class="warning custom-block"><p class="custom-block-title">战斗规则（容易搞混）</p><ul><li><strong>主炮每回合都能射击</strong> —— 不需要装填</li><li><strong>只有鱼雷按回合装填</strong> —— 每回合装填一发</li></ul><p>所以如果主炮显示可以打却打不出去，那是<strong>真问题</strong>，不是机制。这时候看日志页有没有错误。</p></div><h3 id="关于倍速" tabindex="-1">关于倍速 <a class="header-anchor" href="#关于倍速" aria-label="Permalink to &quot;关于倍速&quot;">​</a></h3><p>如果「当前倍速」显示的不是 <code>1.0</code>，那你的游戏时间流速<strong>和原版不一样</strong>。</p><div class="tip custom-block"><p class="custom-block-title">这是解释「点了发射后什么都没了」的关键</p><p>倍速调到 <code>x3</code> 时，按发射后整个战斗会瞬间推进完，看起来像「什么都没发生」。</p><p><strong>看到倍速不是 x1，先点倍速按钮调回 x1</strong>，再试一次。</p><p>详见 <a href="/AtlanticFleetSite/docs/use/timescale">倍速与时间缩放</a>。</p></div><h2 id="运行状态" tabindex="-1">运行状态 <a class="header-anchor" href="#运行状态" aria-label="Permalink to &quot;运行状态&quot;">​</a></h2><p>这一部分列出框架各部分的运行情况，比如：</p><ul><li>Mod 加载状态</li><li>参数系统状态</li><li>模型加载状态</li></ul><h2 id="一个实用技巧" tabindex="-1">一个实用技巧 <a class="header-anchor" href="#一个实用技巧" aria-label="Permalink to &quot;一个实用技巧&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">用状态页验证「Mod 到底生效了没」</p><p>装了 Mod 但不确定有没有效果？</p><ol><li>打开状态页 → 看偏离清单</li><li><strong>如果 Mod 的参数出现在清单里</strong> → 说明生效了</li><li><strong>如果清单是空的</strong> → Mod 没加载成功，去 Mod 页和日志页排查</li></ol><p>这比进战斗实际测试快得多。</p></div><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><h3 id="偏离清单是空的-但我确实改了参数" tabindex="-1">偏离清单是空的，但我确实改了参数 <a class="header-anchor" href="#偏离清单是空的-但我确实改了参数" aria-label="Permalink to &quot;偏离清单是空的，但我确实改了参数&quot;">​</a></h3><p>可能的原因：</p><ol><li><strong>改了但没重开游戏</strong> —— 参数在启动时读取，改了要重开才写入</li><li><strong>改的值正好等于默认值</strong> —— 比如你把 <code>1.0</code> 改成 <code>1.0</code></li><li><strong>滑块拖了但没触发保存</strong> —— 再拖一次</li></ol><h3 id="清单里有奇怪的项" tabindex="-1">清单里有奇怪的项 <a class="header-anchor" href="#清单里有奇怪的项" aria-label="Permalink to &quot;清单里有奇怪的项&quot;">​</a></h3><p>某个参数的当前值不是你预期的。处理方式：</p><ul><li>去参数页找到它，手动调回默认</li><li>或者直接「恢复默认」清空全部</li></ul><h3 id="战斗信息不更新" tabindex="-1">战斗信息不更新 <a class="header-anchor" href="#战斗信息不更新" aria-label="Permalink to &quot;战斗信息不更新&quot;">​</a></h3><p>如果在主菜单（不在战斗中），这部分显示为空是正常的。</p><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li>参数怎么调 → <a href="/AtlanticFleetSite/docs/use/params-page">参数页：调数值</a></li><li>倍速问题 → <a href="/AtlanticFleetSite/docs/use/timescale">倍速与时间缩放</a></li><li>日志详情 → <a href="/AtlanticFleetSite/docs/use/log-page">日志页：自查问题</a></li></ul>`,43)])])}const g=a(r,[["render",l]]);export{u as __pageData,g as default};
